// Staff control tabs use one authorized API; no private table is browser-readable.
async function portalControl(action,data={}){
 const response=await fn('portal-controls',{body:{action,data:{track:ST.track,...data}}});
 if(!response.ok)throw new Error(controlError(response.json.error));return response.json;
}
function controlError(tag){return ({choose_track:'Choose a track at the top first.',select_at_least_five_questions:'Select at least five questions.',quiz_pool_needs_five_valid_questions:'This selection needs at least five eligible multiple-choice questions.',selected_question_unavailable:'One selected question is no longer available. Reload the list and choose again.',questions_need_review:'A selected question changed after review. Check it before releasing.',reset_confirmation_required:'Type RESET to confirm.',admin_required:'Only the administrator can reset student scores.'})[tag]||tag||'Could not save. Please try again.';}
function controlTracks(){return ST.tracks.filter(t=>ST.view!=='revisionAdmin'||['sat','est','est2'].includes(t.id));}
function selectControlTrack(id){
 if(!controlTracks().some(t=>t.id===id))return;
 ST.track=id;$('trackSel').value=id;render();
}
function controlsTrackReady(title){
 const tracks=controlTracks();if(tracks.some(t=>t.id===ST.track))return true;
 $('view').innerHTML=`<div class="head"><h2>${esc(title)}</h2></div><section class="card controls-card"><h3>Choose a track</h3><p>${tracks.length?'Open a track to manage its '+(ST.view==='revisionAdmin'?'revision questions and visibility':ST.view==='quizAdmin'?'daily quiz questions and scores':ST.view==='integrityAdmin'?'exam activity':'student reports')+'.':'No supported tracks are available for this account.'}</p><div class="control-actions" aria-label="Choose a track">${tracks.map(t=>`<button type="button" class="btn" data-control-track="${esc(t.id)}">${esc(t.name)}</button>`).join('')}</div></section>`;
 return false;
}
async function revisionAdmin(){
 if(!controlsTrackReady('Final revision'))return;
 if(!['sat','est','est2'].includes(ST.track)){$('view').innerHTML='<p class="msg">Final revision is available for the mathematics tracks.</p>';return;}
 const track=ST.track,data=await portalControl('revision.list');if(ST.track!==track||ST.view!=='revisionAdmin')return;
 const selected=new Set(),lessons=[...new Set(data.items.map(x=>x.lesson))].sort();
 $('view').innerHTML=`<div class="head"><h2>Final revision</h2><button class="btn" id="revisionVisibility">${data.visible?'Hide from students':'Show to students'}</button></div><p class="msg ${data.visible?'ok':''}" id="revisionVisibilityStatus">${data.visible?'Visible':'Hidden'} for ${esc(ST.tracks.find(t=>t.id===track)?.name||track)}. Hiding closes student access; saved progress is retained.</p><div class="control-bar"><div class="field search"><label for="revisionAdminSearch">Find a question or idea</label><input id="revisionAdminSearch" type="search"></div><div class="field">${select('revisionAdminLesson','Lesson',[['','All lessons'],...lessons.map(l=>[l,l])])}</div><div class="field">${select('revisionAdminStatus','Availability',[['','All'],['released','Released'],['hidden','Hidden']])}</div></div><p class="hint">Choose a lesson, then select its shown questions to release or hide that lesson. Hidden questions are excluded from new sets; previously saved sets retain their questions.</p><div class="control-actions"><button class="btn-sm" id="revisionSelectShown">Select shown</button><button class="btn-sm" id="revisionClear">Clear selection</button><button class="btn" id="revisionRelease">Release selected</button><button class="btn-sm" id="revisionHide">Hide selected</button><span id="revisionSelectedCount" role="status"></span></div><p id="revisionAdminMessage" role="status"></p><div id="revisionAdminTable"></div>`;
 let shown=[];
 const update=()=>{$('revisionSelectedCount').textContent=`${selected.size} selected · ${shown.length} shown`;};
 const paint=()=>{const term=val('revisionAdminSearch').toLowerCase(),lesson=val('revisionAdminLesson'),status=val('revisionAdminStatus');shown=data.items.filter(x=>(!lesson||x.lesson===lesson)&&(!status||(status==='released'?x.active:!x.active))&&[x.lesson,x.idea,x.stem,x.source].join(' ').toLowerCase().includes(term));
 $('revisionAdminTable').innerHTML=wrapTable(`<table><thead><tr><th>Select</th><th>Lesson / idea</th><th>Question</th><th>Level</th><th>Status</th></tr></thead><tbody>${shown.map(x=>`<tr><td><input type="checkbox" data-revision-pick="${x.id}" aria-label="Select ${esc(x.source||x.idea)}" ${selected.has(x.id)?'checked':''}></td><td><b>${esc(x.lesson)}</b><p class="hint">${esc(x.idea)}</p></td><td>${esc(x.source)}<p class="hint">${esc(x.stem)}</p><button type="button" class="btn-sm" data-control-preview="${x.id}">Preview question</button></td><td>${esc(x.difficulty)}</td><td>${!x.ready?'Needs content review':x.active?'Released':'Hidden'}</td></tr>`).join('')}</tbody></table>`);
 document.querySelectorAll('[data-revision-pick]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.revisionPick):selected.delete(el.dataset.revisionPick);update();});update();};
 ['revisionAdminSearch','revisionAdminLesson','revisionAdminStatus'].forEach(id=>$(id).addEventListener(id.includes('Search')?'input':'change',paint));
 $('revisionSelectShown').onclick=()=>{shown.forEach(x=>selected.add(x.id));paint();};$('revisionClear').onclick=()=>{selected.clear();paint();};
 for(const [id,active] of [['revisionRelease',true],['revisionHide',false]])$(id).onclick=async()=>{if(!selected.size){$('revisionAdminMessage').textContent='Select questions first.';return;}$(id).disabled=true;try{const result=await portalControl('revision.release',{track,ids:[...selected],active});if(ST.track!==track||ST.view!=='revisionAdmin')return;data.items.forEach(x=>{if(selected.has(x.id))x.active=active;});selected.clear();paint();$('revisionAdminMessage').textContent=`${result.count} questions ${active?'released':'hidden'}.`;}catch(e){if(ST.track===track&&ST.view==='revisionAdmin'&&$('revisionAdminMessage'))$('revisionAdminMessage').textContent=e.message;}finally{if($(id))$(id).disabled=false;}};
 $('revisionVisibility').onclick=async()=>{const button=$('revisionVisibility');button.disabled=true;try{await portalControl('revision.visibility',{track,visible:!data.visible});if(ST.track===track&&ST.view==='revisionAdmin')await revisionAdmin();}catch(e){if(ST.track===track&&ST.view==='revisionAdmin'&&$('revisionAdminMessage'))$('revisionAdminMessage').textContent=e.message;button.disabled=false;}};paint();
}
async function quizAdmin(){
 if(!controlsTrackReady('Daily quizzes'))return;
 const track=ST.track,data=await portalControl('quiz.list');if(ST.track!==track||ST.view!=='quizAdmin')return;
 const settings=data.settings,selected=new Set(settings.daily_question_ids||[]),lessons=[...new Set(data.questions.map(x=>x.lesson))].sort();
 $('view').innerHTML=`<div class="head"><h2>Daily quizzes</h2><button class="btn-sm" id="assignedQuizzes">Open assigned quizzes</button></div><p class="hint">Five questions per day. Choose the pool below; the portal selects five each day. Selecting exactly five fixes the question set.</p><div class="card controls-card"><h3>Question release</h3>${select('quizMode','Question selection',[['random','Random from the verified bank'],['lessons','Random from selected lessons'],['selected','Only my selected questions']],settings.daily_mode)}<div id="quizLessonOptions"><p class="hint">Choose the lessons students should practise.</p><div class="control-check-grid">${lessons.map(l=>`<label class="check"><input type="checkbox" data-quiz-lesson="${esc(l)}" ${(settings.daily_lessons||[]).includes(l)?'checked':''}>${esc(l)}</label>`).join('')}</div></div><div id="quizQuestionOptions"><div class="control-bar">${field('quizQuestionSearch','Find a question or source')}${select('quizQuestionLesson','Filter lesson',[['','All lessons'],...lessons.map(l=>[l,l])])}</div><p><span id="quizSelectedCount"></span> <button type="button" class="btn-sm" id="quizClearSelection">Clear selection</button></p><div id="quizQuestionList" class="control-question-list"></div></div><p class="msg">${data.today_frozen?'Today’s questions have already been opened and will stay unchanged. These settings apply to future quizzes.':'Changes apply when the next quiz is opened, including today if nobody has opened it.'}</p><button class="btn" id="quizSave">Save question selection</button><p id="quizAdminMessage" role="status"></p></div>
 <div class="card controls-card"><h3>Scores and resets</h3><p class="hint">Daily quiz scores, points and streaks are separate from assigned exams. Resetting a past date changes its history; students can retake only today’s daily quiz.</p>${wrapTable(`<table><thead><tr><th>Student</th><th>Completed days</th><th>Points</th><th>Action</th></tr></thead><tbody>${data.students.map(s=>`<tr><td>${esc(s.name||'Student')}</td><td>${s.completed}</td><td>${s.points}</td><td>${ST.me.role==='admin'?`<button class="btn-sm" data-quiz-reset="${s.id}">Reset…</button>`:'Admin only'}</td></tr>`).join('')}</tbody></table>`)}</div>`;
 $('assignedQuizzes').onclick=()=>{ST.view='exams';syncAdminNavigation();render();};
 let shown=[];const paint=()=>{const term=val('quizQuestionSearch').toLowerCase(),lesson=val('quizQuestionLesson');shown=data.questions.filter(x=>(!lesson||x.lesson===lesson)&&[x.stem,x.source,x.lesson].join(' ').toLowerCase().includes(term));$('quizSelectedCount').textContent=`${selected.size} selected · ${shown.length} matches`;
 $('quizQuestionList').innerHTML=shown.slice(0,150).map(x=>`<label class="check"><input type="checkbox" data-quiz-pick="${x.id}" ${selected.has(x.id)?'checked':''}><span><b>${esc(x.source||x.lesson)}</b> · ${esc(x.stem)}<small>${esc(x.lesson)}</small><button type="button" class="btn-sm" data-control-preview="${x.id}">Preview</button></span></label>`).join('')+(shown.length>150?'<p class="hint">Showing 150 matches. Narrow the search to find more.</p>':'');
 document.querySelectorAll('[data-quiz-pick]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.quizPick):selected.delete(el.dataset.quizPick);$('quizSelectedCount').textContent=`${selected.size} selected · ${shown.length} matches`;});};
 const mode=()=>{$('quizLessonOptions').hidden=val('quizMode')!=='lessons';$('quizQuestionOptions').hidden=val('quizMode')!=='selected';};
 $('quizMode').onchange=mode;$('quizQuestionSearch').oninput=paint;$('quizQuestionLesson').onchange=paint;$('quizClearSelection').onclick=()=>{selected.clear();paint();};
 $('quizSave').onclick=async()=>{const button=$('quizSave');button.disabled=true;try{const result=await portalControl('quiz.save',{track,mode:val('quizMode'),ids:[...selected],lessons:[...document.querySelectorAll('[data-quiz-lesson]:checked')].map(x=>x.dataset.quizLesson)});if(ST.track!==track||ST.view!=='quizAdmin')return;$('quizAdminMessage').textContent=`Saved. ${result.eligible} questions in the pool. ${result.today_frozen?'Today’s opened quiz is unchanged.':'The next quiz will use this selection.'}`;}catch(e){if(ST.track===track&&ST.view==='quizAdmin'&&$('quizAdminMessage'))$('quizAdminMessage').textContent=e.message;}finally{button.disabled=false;}};
 document.querySelectorAll('[data-quiz-reset]').forEach(button=>button.onclick=()=>resetQuizDialog(data.students.find(s=>s.id===button.dataset.quizReset),track));mode();paint();
}
function resetQuizDialog(student,track){
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 dialog('Reset daily progress',`<p class="msg">Student: <b>${esc(student.name)}</b> · Track: <b>${esc(track.toUpperCase())}</b>. The previous records are archived. Exam marks are unchanged.</p>`+select('quizResetMode','What to reset',[['quiz','Quiz answers, scores and points; keep checklist ticks'],['all','All daily progress, including checklist ticks']])+select('quizResetRange','Dates',[['day','One date'],['all','All dates in this track']])+field('quizResetDay','Date',today,'date')+field('quizResetConfirm','Type RESET to confirm'),async()=>{await portalControl('quiz.reset',{track,user_id:student.id,mode:val('quizResetMode'),range:val('quizResetRange'),day:val('quizResetRange')==='day'?val('quizResetDay'):null,confirm:val('quizResetConfirm')});},'Reset progress');
 $('quizResetRange').onchange=()=>{$('quizResetDay').disabled=val('quizResetRange')==='all';};
}
async function reportsAdmin(){
 if(!controlsTrackReady('Reports'))return;
 const track=ST.track,data=await portalControl('reports.list');if(ST.track!==track||ST.view!=='reportsAdmin')return;
 $('view').innerHTML=`<div class="head"><h2>Student reports</h2><span class="pill warn">${data.open_count} open or in review</span></div><p class="hint">Question and site-function reports arrive here. Open a report to mark it in review or resolved and leave a staff note.</p><div class="control-bar">${select('reportStatus','Status',[['all','All reports'],['open','Open'],['in_review','In review'],['resolved','Resolved'],['dismissed','Dismissed']])}${field('reportSearch','Search reports')}</div><div id="reportsList"></div>`;
 const paint=()=>{const status=val('reportStatus'),term=val('reportSearch').toLowerCase();const rows=data.items.filter(r=>(status==='all'||r.status===status)&&[r.student,r.message,r.source,r.screen].join(' ').toLowerCase().includes(term));$('reportsList').innerHTML=rows.length?rows.map(r=>`<article class="card controls-card"><div class="head"><h3>${r.kind==='question'?'Question report':'Site problem'}</h3><span class="pill">${esc(r.status.replace('_',' '))}</span></div><p class="hint">${esc(r.student)} · ${esc(new Date(r.created_at).toLocaleString())} · ${esc(r.screen)}</p>${r.source||r.question_stem?`<p><b>${esc(r.source||'Question')}</b> ${esc(r.question_stem||'')}</p>`:''}<p class="report-message">${esc(r.message)}</p>${r.staff_note?`<p class="hint">Staff note: ${esc(r.staff_note)}</p>`:''}<button class="btn-sm" data-report-manage="${r.id}">Manage report</button>${r.question_id?` <button class="btn-sm" data-control-preview="${r.question_id}">View question</button>`:''}</article>`).join(''):'<p class="msg">No reports match this view.</p>';
 document.querySelectorAll('[data-report-manage]').forEach(b=>b.onclick=()=>{const report=data.items.find(x=>x.id===b.dataset.reportManage);dialog('Manage report',`<p class="report-message">${esc(report.message)}</p>`+select('reportNewStatus','Status',[['open','Open'],['in_review','In review'],['resolved','Resolved'],['dismissed','Dismissed']],report.status)+area('reportNote','Staff note',report.staff_note),()=>portalControl('reports.update',{track,id:report.id,status:val('reportNewStatus'),note:val('reportNote')}));});};
 $('reportStatus').onchange=paint;$('reportSearch').oninput=paint;paint();
}
function syncAdminNavigation(){
 document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('on',b.dataset.v===ST.view);b.setAttribute('aria-current',b.dataset.v===ST.view?'page':'false');});
 const select=document.getElementById('adminSection');if(select)select.value=ST.view;
}
document.getElementById('adminSection')?.addEventListener('change',event=>{ST.view=event.target.value;syncAdminNavigation();render();});

document.addEventListener('click',event=>{const track=event.target.closest?.('[data-control-track]');if(track){selectControlTrack(track.dataset.controlTrack);return;}const b=event.target.closest?.('[data-control-preview]');if(b){event.preventDefault();openTeachingExam({title:'Question preview',question_ids:[b.dataset.controlPreview]});}});
